---
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/jessitron/mtg-deck-shuffler/contracts/payloads/table.created.v1.json",
  "title": "table.created payload, schemaVersion 1",
  "description": "A table came into being. The Spine mints the tableId (it's on the envelope); the name here is a lookup alias, unique among active tables only.",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "minLength": 1,
      "description": "The table's human name — the thing you say over Discord. A lookup alias, not an identity."
    },
    "creator": {
      "type": "string",
      "minLength": 1,
      "description": "Display name of whoever created the table."
    }
  },
  "required": ["name", "creator"],
  "additionalProperties": true
}
---seat.taken---
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/jessitron/mtg-deck-shuffler/contracts/payloads/seat.taken.v1.json",
  "title": "seat.taken payload, schemaVersion 1",
  "description": "Someone sat down. Player names are not unique; seat identity is its own thing (the seatId). Spectators never take a seat — they need nothing.",
  "type": "object",
  "properties": {
    "seatId": {
      "type": "string",
      "minLength": 8,
      "description": "A short GUID identifying this seat-taking. Seat identity is distinct from the player's display name."
    },
    "seat": {
      "type": "integer",
      "minimum": 1,
      "maximum": 4,
      "description": "Seat number at the table, 1-4."
    },
    "playerName": {
      "type": "string",
      "minLength": 1,
      "description": "Display only. Not unique, not an identity."
    }
  },
  "required": ["seatId", "seat", "playerName"],
  "additionalProperties": true
}
---seat.joined---
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/jessitron/mtg-deck-shuffler/contracts/payloads/seat.joined.v1.json",
  "title": "seat.joined payload, schemaVersion 1",
  "description": "A seat joins its table at Shuffle Up, carrying how this player's stuff should look: their deck's name for the name label, their playmat, and their sleeve. Sent before any card so the table can draw the whole player area first. Sleeves are optional; when sleeveColor is present it wins over cardBackImageUrl, and an unsleeved seat keeps the standard Magic card back. Who joined (seatId, playerName) lives on the envelope's initiator, not repeated here.",
  "type": "object",
  "properties": {
    "deckName": {
      "type": "string",
      "minLength": 1,
      "description": "The deck's display name, player-chosen content — verbatim, no truncation. Shown with the player name on the seat's name label."
    },
    "playmatImageUrl": {
      "type": "string",
      "format": "uri",
      "description": "Absolute URL of this seat's playmat art; opaque to the receiver."
    },
    "cardBackImageUrl": {
      "type": "string",
      "format": "uri",
      "description": "Absolute URL of the card-back image. Omitted when a sleeve is defined; sleeveColor wins if both arrive."
    },
    "sleeveColor": {
      "type": "string",
      "pattern": "^#[0-9a-fA-F]{6}$",
      "description": "The seat's sleeve as a solid color (hex). Player identity data — commander-damage counters need the raw hex. A game constant: chosen before the game, never changed mid-game."
    },
    "primaryColor": {
      "type": "string",
      "pattern": "^#[0-9a-fA-F]{6}$",
      "description": "The seat's resolved identity color (hex): the sleeve color when one is chosen, otherwise the darker of the playmat's curated pair. Optional and additive — an older Shuffler build may send sleeveColor alone."
    },
    "secondaryColor": {
      "type": "string",
      "pattern": "^#[0-9a-fA-F]{6}$",
      "description": "The seat's resolved secondary identity color (hex), contrasting with primaryColor. Optional and additive — an older Shuffler build may send sleeveColor alone."
    },
    "commanders": {
      "type": "array",
      "minItems": 0,
      "maxItems": 2,
      "description": "0-2 commanders, ordinary GameCards in the CommandZone location. No face — a commander always arrives in the command zone face up; flipping it there afterward is table-local.",
      "items": {
        "type": "object",
        "properties": {
          "card": {
            "type": "object",
            "properties": {
              "scryfallId": {
                "type": "string",
                "format": "uuid",
                "description": "Definition: the exact printing — oracle identity, all faces, all names, all images derivable."
              },
              "instanceId": {
                "type": "string",
                "format": "uuid",
                "description": "Instance: this particular physical-ish card, minted per game at game start."
              }
            },
            "required": ["scryfallId", "instanceId"],
            "additionalProperties": true
          },
          "cardName": {
            "type": "string",
            "minLength": 1,
            "description": "Blessed scaffolding convenience: display without a Scryfall lookup. Same pre-Spine exception as card.played (ticket 05)."
          },
          "frontImageUrl": {
            "type": "string",
            "format": "uri",
            "description": "Blessed scaffolding convenience: render without a Scryfall lookup."
          },
          "backImageUrl": {
            "type": ["string", "null"],
            "description": "Present (non-null) exactly when the card has a printed back face — null, never omitted, when it doesn't (two-faced-cards watch point 17)."
          }
        },
        "required": ["card", "cardName", "frontImageUrl", "backImageUrl"],
        "additionalProperties": true
      }
    },
    "gameCardIndex": {
      "type": "integer",
      "minimum": 0,
      "description": "Same field as card.played's gameCardIndex, allowed here for symmetry now that the guard is gone (let-gamecardindex-out, 2026-08-10) — unused today since seat.joined describes a seat, not a single card, but no longer specially forbidden either."
    }
  },
  "required": ["deckName"],
  "additionalProperties": true
}

